#include <stdexcept>
using namespace std;

class IntStack {
private:
    int* arr;
    int top;
    int capacity;

public:
    IntStack(int capacity) : capacity(capacity), top(-1) {
        arr = new int[capacity];
    }

    ~IntStack() {
        delete[] arr;
    }

    bool isEmpty() {
        return top == -1;
    }

    bool isFull() {
        return top == capacity - 1;
    }

    void push(int value) {
        if (isFull()) {
            throw runtime_error("Stack Overflow");
        }
        arr[++top] = value;
    }

    int pop() {
        if (isEmpty()) {
            throw runtime_error("Stack Underflow");
        }
        return arr[top--];
    }

    int peek() {
        if (isEmpty()) {
            throw runtime_error("Stack is Empty");
        }
        return arr[top];
    }
};
